// Converte o payload do provedor para o contrato canônico InboundMessage.
// TODO(provedor): ajustar os caminhos abaixo ao formato do provedor aprovado (ponto A1).
const body = $input.first().json.body ?? $input.first().json;
const m = body.message ?? body;

const out = {
  providerMessageId: String(m.id ?? m.key?.id ?? ''),
  groupId: String(m.chatId ?? m.key?.remoteJid ?? m.from ?? ''),
  senderId: String(m.author ?? m.key?.participant ?? m.sender ?? ''),
  receivedAt: new Date((m.timestamp ?? m.messageTimestamp ?? Date.now() / 1000) * 1000).toISOString(),
  text: m.text ?? m.body ?? m.caption ?? m.message?.conversation ?? null,
  media: null,
  location: null,
};

if (m.mimetype || m.media?.mimetype || m.message?.imageMessage) {
  out.media = {
    mimeType: m.mimetype ?? m.media?.mimetype ?? 'image/jpeg',
    url: m.mediaUrl ?? m.media?.url ?? null,
    base64: m.media?.base64 ?? null,
    capturedAt: null,
  };
  if (!out.text && m.media?.caption) out.text = m.media.caption;
}

const loc = m.location ?? m.message?.locationMessage ?? m.message?.liveLocationMessage;
if (loc) {
  out.location = {
    latitude: Number(loc.latitude ?? loc.degreesLatitude),
    longitude: Number(loc.longitude ?? loc.degreesLongitude),
    isLive: Boolean(m.message?.liveLocationMessage) || loc.isLive === true,
  };
}

if (!out.providerMessageId || !out.groupId) {
  return [{ json: { skip: true, reason: 'payload sem id de mensagem ou grupo' } }];
}
return [{ json: out }];
